/* Message ratio layout follows the Shenzhen source screenshot; values retain their own dated capture. */
'use strict';
window.AdminMessageStatsAligned=(()=>{
 const route='messageStats',names=['微信使用数','碎银微信数','企微使用数','碎银企微数'],colors=['#5470c6','#91cc75','#fac858','#73c0de'];
 const date=s=>/^\d{8}$/.test(s)?s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6):s;
 const valid=s=>/^\d{4}-\d\d-\d\d$/.test(s)&&Number.isFinite(Date.parse(s+'T00:00:00Z'))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;
 function render(){
  const A=window.Admin,{node}=A,root=node('div','page message-parity-page');A.$('app').replaceChildren(root);
  const btn=(label,run,cls='')=>{const b=node('button',cls,label);b.type='button';b.onclick=run;return b;};
  let data=null,query=null,loading=false,failed=false,hidden=new Set(),resize;
  const form=node('form','message-filters'),dates=node('div','message-dates'),from=node('input'),to=node('input'),cal=btn('',()=>{},'message-calendar-open');
  cal.dataset.dateOpen='';cal.setAttribute('aria-label','打开统计日期日历');cal.innerHTML='<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M7 3v4m10-4v4M3 10h18" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>';
  for(const [input,label]of [[from,'开始日期'],[to,'结束日期']]){input.type='text';input.placeholder=label;input.setAttribute('aria-label',label);input.maxLength=10;input.autocomplete='off';}
  dates.append(cal,from,node('span','','至'),to);const dateField=node('label','message-filter-field');dateField.append(node('span','','统计时间'),dates);
  const period=node('select');period.setAttribute('aria-label','统计周期');period.append(new Option('自然日','day'));const periodControl=A.searchableSelect(period,'统计周期');periodControl.classList.add('message-period');
  const persona=node('select');persona.setAttribute('aria-label','微信号');persona.append(new Option('全部人设',''));
  for(const value of A.optionsFor('微信号'))if(value&&!/^全部/.test(value))persona.append(new Option(value,value));
  const personaField=node('label','message-filter-field message-persona');personaField.append(node('span','','微信号'),A.searchableSelect(persona,'微信号'));
  const exclude=node('input'),excludeField=node('label','message-exclude');exclude.type='checkbox';excludeField.append(exclude,document.createTextNode('排除群发消息'));
  const search=btn('搜索',()=>{},'message-search');search.type='submit';search.onclick=null;search.prepend(node('span','message-search-icon'));const reset=btn('重置',resetAll);
  form.append(dateField,periodControl,personaField,excludeField,search,reset);form.onsubmit=e=>{e.preventDefault();submit();};
  const error=node('p','message-validation');error.hidden=true;error.setAttribute('role','alert');
  const card=node('section','message-stat-card'),heading=node('div','message-stat-heading'),title=node('h2','','消息占比'),info=btn('i',explain,'message-info'),total=node('strong','message-total','—'),chart=node('div','message-plot');
  info.setAttribute('aria-label','消息占比口径及样本来源');title.append(info);heading.append(title,total);card.append(heading,chart);root.append(form,error,card);
  const picker=window.AdminUsageDatePicker?.attach({host:dates,start:from,end:to,getMode:()=> 'range',onChange:()=>{}});
  function explain(){const detail=node('div');detail.append(node('p','',data?.sourceKind==='mock'?'当前为合成演示趋势。':'当前为本租户固定日期的统计快照。'),node('p','',data?`${data.filters?.from||date(data.points?.[0]?.date||'')} 至 ${data.filters?.to||date(data.points?.at(-1)?.date||'')}；采集时间 ${data.captured_at||'未记录'}。`:'尚未加载样本'),node('p','','碎银占比 =（碎银微信数 + 碎银企微数）/ 四类消息总数。缺少的日期或人设拆分不会由其他租户补数。'));A.showDialog('消息占比',detail,[{label:'关闭',run:A.closeDialog}]);}
  function defaults(){from.value=data?.filters?.from||date(data?.points?.[0]?.date||'');to.value=data?.filters?.to||date(data?.points?.at(-1)?.date||'');persona.value='';persona.dispatchEvent(new Event('change'));period.value='day';exclude.checked=false;}
  function resetAll(){picker?.close();defaults();submit();}
  function submit(){if(loading)return;const start=from.value.trim(),end=to.value.trim();error.hidden=true;if(!valid(start)||!valid(end)||start>end){error.textContent='请输入有效起止日期，开始日期不能晚于结束日期';error.hidden=false;return;}picker?.close();query={start,end,persona:persona.value,exclude:exclude.checked};draw();}
  function selectedPoints(){if(!data||!query||query.persona)return [];const capturedFrom=data.filters?.from||date(data.points?.[0]?.date||''),capturedTo=data.filters?.to||date(data.points?.at(-1)?.date||'');if(query.start<capturedFrom||query.end>capturedTo)return [];let points=(data.points||[]).filter(p=>date(p.date)>=query.start&&date(p.date)<=query.end);
   if(query.exclude){if(data.sourceKind!=='mock')return [];points=points.map(p=>{const series=Object.fromEntries(Object.entries(p.series).map(([k,v])=>[k,{...v,count:v.count-(v.massCount||0)}]));const total=Object.values(series).reduce((n,v)=>n+v.count,0);return {...p,series,total,displayedSuiyinPercent:total?(series['碎银微信数'].count+series['碎银企微数'].count)/total*100:0};});}return points;}
  function draw(){
   chart.replaceChildren();if(loading){chart.dataset.state='loading';chart.append(node('div','message-state','正在加载…'));return;}if(failed){chart.dataset.state='error';chart.append(node('div','message-state','统计样本加载失败'),btn('重试',load,'message-retry'));return;}
   const points=selectedPoints();total.textContent=points.length?points.reduce((n,p)=>n+p.total,0).toLocaleString():'—';info.title=(data.sourceKind==='mock'?'演示样本':'本租户采样')+' · '+(data.filters?.from||date(data.points?.[0]?.date||''))+' 至 '+(data.filters?.to||date(data.points?.at(-1)?.date||''));
   if(!points.length){chart.dataset.state='not-captured';chart.append(node('div','message-state','当前筛选的趋势样本尚未采集'));return;}chart.dataset.state='ready';
   const legend=node('div','message-legend');names.forEach((name,i)=>{const b=btn(name,()=>{hidden.has(name)?hidden.delete(name):hidden.add(name);draw();});b.classList.toggle('is-hidden',hidden.has(name));b.setAttribute('aria-pressed',String(!hidden.has(name)));const mark=node('i');mark.style.background=colors[i];b.prepend(mark);legend.append(b);});const ratio=btn('碎银占比',()=>{hidden.has('ratio')?hidden.delete('ratio'):hidden.add('ratio');draw();},'ratio-legend');ratio.classList.toggle('is-hidden',hidden.has('ratio'));ratio.setAttribute('aria-pressed',String(!hidden.has('ratio')));ratio.prepend(node('i'));legend.append(ratio);chart.append(legend);
   const width=Math.max(700,chart.clientWidth||1188),height=356,left=88,right=90,top=69,bottom=28,plotH=height-top-bottom,plotW=width-left-right,max=A.tenant==='yestar-sz'?500000:Math.ceil(Math.max(...points.map(p=>p.total))/50000)*50000||1,step=plotW/points.length;
   const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',String(width));svg.setAttribute('height',String(height));svg.setAttribute('role','img');svg.setAttribute('aria-label','四类消息堆叠柱形与碎银占比折线');let html=`<text x="${left}" y="${top-18}" text-anchor="middle" fill="#909399" font-size="12">使用数</text><text x="${width-right}" y="${top-18}" text-anchor="middle" fill="#909399" font-size="12">占比</text>`;
   for(let i=0;i<=5;i++){const y=top+plotH*i/5;html+=`<line x1="${left}" x2="${width-right}" y1="${y}" y2="${y}" stroke="#e0e6f1"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#6e7079" font-size="12">${Math.round(max*(1-i/5)).toLocaleString()}</text><text x="${width-right+10}" y="${y+4}" fill="#6e7079" font-size="12">${100-i*20} %</text>`;}
   html+=`<line x1="${left}" x2="${left}" y1="${top}" y2="${height-bottom}" stroke="#6e7079"/><line x1="${left}" x2="${width-right}" y1="${height-bottom}" y2="${height-bottom}" stroke="#6e7079"/>`;/* category ticks */for(let i=0;i<=points.length;i++){const x=left+step*i;html+=`<line x1="${x}" x2="${x}" y1="${height-bottom}" y2="${height-bottom+5}" stroke="#6e7079"/>`;}const poly=[];
   points.forEach((p,i)=>{const x=left+step*i+step*.15,w=step*.7;let y=height-bottom;names.forEach((name,n)=>{if(hidden.has(name))return;const h=(p.series[name]?.count||0)/max*plotH;y-=h;html+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${colors[n]}"/>`;});const center=x+w/2,ratioY=top+plotH*(1-p.displayedSuiyinPercent/100);poly.push([center,ratioY]);html+=`<text x="${center}" y="${height-10}" text-anchor="middle" fill="#6e7079" font-size="12">${date(p.date).replaceAll('-','')}</text>`;});
   if(!hidden.has('ratio')){html+=`<polyline fill="none" stroke="#ff6e76" stroke-width="2" points="${poly.map(p=>p.join(',')).join(' ')}"/>`;poly.forEach(([x,y])=>html+=`<circle cx="${x}" cy="${y}" r="2.5" fill="#fff" stroke="#ff6e76" stroke-width="1.5"/>`);}
   points.forEach((p,i)=>html+=`<rect data-point="${i}" x="${left+step*i}" y="${top}" width="${step}" height="${plotH}" fill="transparent" tabindex="0" role="button" aria-label="${date(p.date)} 消息明细"/>`);svg.innerHTML=html;chart.append(svg);
   const tooltip=node('div','message-chart-tooltip');tooltip.hidden=true;chart.append(tooltip);svg.querySelectorAll('[data-point]').forEach(r=>{const show=e=>{const p=points[Number(r.dataset.point)];tooltip.replaceChildren(node('strong','',date(p.date)));names.forEach((name,i)=>{const row=node('div'),mark=node('i');mark.style.background=colors[i];row.append(mark,document.createTextNode(`${name}  ${Number(p.series[name]?.count||0).toLocaleString()}`));tooltip.append(row);});tooltip.append(node('div','',`碎银占比  ${p.displayedSuiyinPercent}%`));tooltip.hidden=false;const rect=chart.getBoundingClientRect();tooltip.style.left=Math.max(0,Math.min((e.clientX||rect.left+100)-rect.left+12,chart.clientWidth-245))+'px';tooltip.style.top=Math.max(32,Math.min((e.clientY||rect.top+100)-rect.top+12,chart.clientHeight-165))+'px';};r.onmousemove=show;r.onfocus=show;r.onmouseleave=()=>tooltip.hidden=true;r.onblur=()=>tooltip.hidden=true;});
  }
  async function load(){loading=true;failed=false;draw();try{const res=await fetch('data/content/message-chart-'+A.tenant+'.json');if(!res.ok)throw Error('load');const value=await res.json();if(value.tenant!==A.tenant||!Array.isArray(value.points))throw Error('tenant mismatch');data=value;defaults();query={start:from.value,end:to.value,persona:'',exclude:false};}catch{failed=true;}finally{loading=false;draw();}}
  load();if(window.ResizeObserver){let lastWidth=0;resize=new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(data&&Math.abs(width-lastWidth)>2){lastWidth=width;draw();}});resize.observe(chart);window.addEventListener('pagehide',()=>resize.disconnect(),{once:true});}return true;
 }
 const views=window.AdminViews,previous=views.render;views.render=function(){return window.Admin.route===route?render():previous.apply(this,arguments);};return {render};
})();
